const readImageData=file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result||''));reader.onerror=()=>reject(new Error('تعذر قراءة الصورة'));reader.readAsDataURL(file)});
const compressImage=source=>new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{const scale=Math.min(1,512/Math.max(image.naturalWidth,image.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.naturalWidth*scale));canvas.height=Math.max(1,Math.round(image.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.drawImage(image,0,0,canvas.width,canvas.height);const result=canvas.toDataURL('image/webp',.62);if(result.length>380000)reject(new Error('حجم المخطط كبير. ارفع صورة أصغر أو قلل دقتها.'));else resolve(result)};image.onerror=()=>reject(new Error('تعذر تجهيز صورة المخطط'));image.src=source});
const projectProgress=(id,s=getState())=>{const items=s.tasks.filter(t=>(t.project||t.projectId)===id);if(items.length)return Math.round(items.filter(t=>t.status==='مكتملة').length/items.length*100);return Number(s.projects.find(p=>p.id===id)?.progress||0)};
const fmtDate=(s)=>{if(!s)return '—';const d=new Date(`${s}T00:00:00`);return new Intl.DateTimeFormat(getState().settings.language==='en'?'en-US':'ar-SA',{day:'numeric',month:'short'}).format(d)};
