 '<aside class="panel panel-pad"><div class="panel-head"><div><h2>بيانات المشروع</h2><p>سياق مباشر من مساحة العمل المصرح بها</p></div></div>'+(project?'<div class="module-rows">'+[['الطلبات',rows(s.clientRequests).length],['الملفات',rows(s.files).length],['المهام',rows(s.tasks).length],['القرارات',rows(s.decisions).length]].map(([name,count])=>'<article class="module-row"><div class="module-main"><h3>'+name+'</h3></div><strong>'+count+'</strong></article>').join('')+'</div>':'<div class="empty-state">لا توجد مشاريع متاحة لهذا الحساب.</div>')+'<div class="notice warn" style="margin-top:12px">مخرجات الذكاء الاصطناعي مساعدة للمراجعة ولا تعتمد مخططًا أو قرارًا للتنفيذ.</div></aside></div>';
