const translateUiText=(value)=>{const exact=englishText[value.trim()];if(exact)return value.replace(value.trim(),exact);let out=value;for(const [ar,en] of Object.entries(englishText).sort((a,b)=>b[0].length-a[0].length)){if(ar.length>1&&out.includes(ar))out=out.split(ar).join(en)}return out.replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d))};
function localizeUi(){if(getState().settings.language!=='en')return;const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.parentElement?.closest('script,style,svg,[data-no-translate]'))continue;node.nodeValue=translateUiText(node.nodeValue)}document.querySelectorAll('[placeholder],[aria-label],[title]').forEach(el=>['placeholder','aria-label','title'].forEach(attr=>{const value=el.getAttribute(attr);if(value)el.setAttribute(attr,translateUiText(value))}));const pageTitle={overview:'Overview',home:'Home',projects:'Projects',workspace:'Project workspace',changes:'Engineering changes',thread:'Project links',tasks:'Tasks',files:'Files & revisions',approvals:'Approvals',team:'Team',settings:'Preferences',consultations:'Consultations',client:'Client portal','client-requests':'Client requests',ai:'KHALIYA AI',reports:'Reports',decisions:'Engineering decisions',meetings:'Meetings',clients:'Clients',schedule:'Schedule',boq:'Quantities & cost',timeline:'Project history'}[page]||'Workspace';document.title=`${pageTitle} | KHALIYA`}
