    const project=getState().projects.find(p=>p.id===v('project'));
    const decision={id:makeId('DEC'),title:v('title'),description:v('description'),project:v('project'),status:'مسودة',ownerUid:user.uid,visibleTo:[...new Set([user.uid,...(project?.managerUids||[]),...(project?.officeManagerUids||[])])]};
